import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';
import {
  ArrowForward as ArrowForwardIcon,
  Download as DownloadIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import { frameworkReadinessLabel } from '../../constants/reportReadinessLabels';
import {
  defaultExportFileName,
  isExportFormatClientAllowed,
  mapReportingDateRange,
  reportTypeForTab,
  statutoryExportFormatsForTab,
  verificationExportFormatsForTab,
  type ReportingExportFormatOption,
} from '../../constants/reportingExports';
import {
  msmeShareStatusLabel,
  msmeStatutorySectionSubtitle,
  msmeStatutorySectionTitle,
  remediationLinkForBlockedReason,
} from '../../constants/reportingUxLabels';
import { msmeExportPrimaryAction } from '../../constants/msmeSimplifiedUi';
import useReadinessLocale from '../../hooks/useReadinessLocale';

type NotifySeverity = 'success' | 'error' | 'warning' | 'info';

interface ExportRemediation {
  reportReadinessLevel?: string;
  reportReadinessLabel?: string;
  filingDisclaimer?: string | null;
  cbamBlockedReasons?: string[];
}

interface ReportingStatutoryExportsProps {
  tabValue: number;
  dateRange: string;
  companyName?: string | null;
  readinessLevel?: string | null;
  readinessLabel?: string | null;
  readinessType?: string | null;
  blockedReasons?: string[];
  prioritizedActions?: Array<{ action: string; hubLink?: string | null }>;
  period?: string;
  exportApplicable?: boolean;
  onOrchestrationComplete?: () => void;
  simplifiedMode?: boolean;
  onNotify: (message: string, severity: NotifySeverity) => void;
}

const downloadBlob = (blob: Blob, fileName: string) => {
  const blobUrl = window.URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = blobUrl;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.URL.revokeObjectURL(blobUrl);
};

const extractRemediation = (error: unknown): ExportRemediation | null => {
  if (!error || typeof error !== 'object') {
    return null;
  }
  const response = (error as { response?: { data?: { remediation?: ExportRemediation } } }).response;
  return response?.data?.remediation ?? null;
};

const formatRequirementLabel = (format: ReportingExportFormatOption): string => {
  if (format.id === 'audit-pack') {
    return frameworkReadinessLabel('ISO14064', format.minReadinessLevel);
  }
  if (format.id === 'pcf-pack') {
    return frameworkReadinessLabel('ISO14067', format.minReadinessLevel);
  }
  if (format.id === 'registry') {
    return frameworkReadinessLabel('CBAM', format.minReadinessLevel);
  }
  return frameworkReadinessLabel('BRSR', format.minReadinessLevel);
};

const ReportingStatutoryExports: React.FC<ReportingStatutoryExportsProps> = ({
  tabValue,
  dateRange,
  companyName,
  readinessLevel,
  readinessLabel,
  blockedReasons = [],
  prioritizedActions = [],
  period = 'annual',
  exportApplicable = false,
  onOrchestrationComplete,
  simplifiedMode = false,
  onNotify,
}) => {
  const { strings } = useReadinessLocale();
  const [busyFormatId, setBusyFormatId] = useState<string | null>(null);
  const [orchestrating, setOrchestrating] = useState(false);
  const [lastRemediation, setLastRemediation] = useState<ExportRemediation | null>(null);

  const reportType = reportTypeForTab(tabValue);
  const statutoryFormats = useMemo(() => statutoryExportFormatsForTab(tabValue), [tabValue]);
  const verificationFormats = useMemo(() => verificationExportFormatsForTab(tabValue), [tabValue]);

  const primaryGap = useMemo(() => {
    if (prioritizedActions[0]?.hubLink) {
      return {
        label: prioritizedActions[0].action,
        link: prioritizedActions[0].hubLink,
      };
    }
    if (blockedReasons[0]) {
      return {
        label: blockedReasons[0],
        link: remediationLinkForBlockedReason(blockedReasons[0]) || '/compliance',
      };
    }
    if (readinessLevel && readinessLevel !== 'filing_ready') {
      return {
        label: readinessLabel
          || frameworkReadinessLabel(
            reportType === 'iso14064' ? 'ISO14064' : reportType === 'cbam' ? 'CBAM' : 'BRSR',
            readinessLevel
          ),
        link: '/compliance',
      };
    }
    return null;
  }, [prioritizedActions, blockedReasons, readinessLevel, readinessLabel, reportType]);

  const exportLockGap = useMemo(() => {
    if (primaryGap) return primaryGap;
    if (readinessLevel && readinessLevel !== 'filing_ready') {
      return {
        label: readinessLabel
          || frameworkReadinessLabel(
            reportType === 'iso14064' ? 'ISO14064' : reportType === 'cbam' ? 'CBAM' : 'BRSR',
            readinessLevel
          ),
        link: '/compliance',
      };
    }
    return {
      label: 'Complete readiness checks before statutory export.',
      link: '/compliance',
    };
  }, [primaryGap, readinessLevel, readinessLabel, reportType]);

  const exportPrimaryAction = useMemo(() => {
  if (!simplifiedMode || !exportLockGap || !exportLockGap.link) {
    return null;
  }

  return msmeExportPrimaryAction({
    label: exportLockGap.label,
    link: exportLockGap.link,
  });
}, [simplifiedMode, exportLockGap]);

  // const exportPrimaryAction = useMemo(
  //   () => (simplifiedMode ? msmeExportPrimaryAction(primaryGap) : null),
  //   [simplifiedMode, primaryGap]
  // );

  if (!reportType || (statutoryFormats.length === 0 && verificationFormats.length === 0)) {
    return null;
  }

  const shareStatus = msmeShareStatusLabel(readinessLevel);
  const currentReadinessLabel = readinessLabel
    || frameworkReadinessLabel(
      reportType === 'iso14064' ? 'ISO14064' : reportType === 'cbam' ? 'CBAM' : 'BRSR',
      readinessLevel || 'prep_draft'
    );

  const handleDownload = async (format: ReportingExportFormatOption) => {
    if (!isExportFormatClientAllowed(format, readinessLevel)) {
      onNotify(
        strings.statutoryLockedHint.replace('{format}', format.label).replace('{requirement}', formatRequirementLabel(format)),
        'warning'
      );
      return;
    }

    setBusyFormatId(format.id);
    setLastRemediation(null);

    try {
      const { blob, fileName } = await ApiService.exportReportArtifact({
        reportType,
        format: format.apiFormat,
        dateRange: mapReportingDateRange(reportType, dateRange),
      });
      downloadBlob(blob, fileName || defaultExportFileName(reportType, format, companyName || 'MSME'));
      onNotify(strings.statutoryDownloadSuccess.replace('{format}', format.label), 'success');
    } catch (error: unknown) {
      const remediation = extractRemediation(error);
      if (remediation) {
        setLastRemediation(remediation);
      }
      const message = error instanceof Error ? error.message : `Failed to export ${format.label}.`;
      onNotify(message, 'error');
    } finally {
      setBusyFormatId(null);
    }
  };

  const allStatutoryAllowed = statutoryFormats.every((format) => isExportFormatClientAllowed(format, readinessLevel));

  const runPreExportOrchestration = async () => {
    setOrchestrating(true);
    try {
      await ApiService.orchestrateReportingReadiness({
        period,
        actionLimit: 8,
        runAutopilot: true,
        includeBrsrOrchestration: true,
        includeIsoOrchestration: true,
        includePcfOrchestration: exportApplicable,
        includeCbamOrchestration: exportApplicable,
      });
      onNotify('Readiness check complete — try your export again.', 'success');
      onOrchestrationComplete?.();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Readiness orchestration failed.';
      onNotify(message, 'error');
    } finally {
      setOrchestrating(false);
    }
  };

  return (
    <Box sx={{ mt: 2 }}>
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
        {msmeStatutorySectionTitle}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        {msmeStatutorySectionSubtitle}
      </Typography>

      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1.5 }}>
        <Chip
          size="small"
          label={shareStatus}
          color={readinessLevel === 'filing_ready' ? 'success' : 'primary'}
          variant="outlined"
        />
        <Chip size="small" label={currentReadinessLabel} variant="outlined" />
      </Stack>

      {!allStatutoryAllowed ? (
        <Alert
          severity="warning"
          sx={{ mb: 1.5 }}
          action={(
            simplifiedMode && exportPrimaryAction ? (
              exportPrimaryAction.type === 'link' ? (
                <Button
                  color="inherit"
                  size="small"
                  component={RouterLink}
                  to={exportPrimaryAction.link || '/document-upload'}
                  endIcon={<ArrowForwardIcon />}
                >
                  {exportPrimaryAction.label}
                </Button>
              ) : (
                <Button
                  color="inherit"
                  size="small"
                  disabled={orchestrating}
                  onClick={() => void runPreExportOrchestration()}
                >
                  {orchestrating ? 'Checking…' : exportPrimaryAction.label}
                </Button>
              )
            ) : (
              <Stack direction="row" spacing={0.5}>
                <Button
                  color="inherit"
                  size="small"
                  disabled={orchestrating}
                  onClick={() => void runPreExportOrchestration()}
                >
                  {orchestrating ? 'Checking…' : strings.checkReadinessFirst}
                </Button>
                <Button
                  color="inherit"
                  size="small"
                  component={RouterLink}
                  to={exportLockGap.link || '/compliance'}
                  endIcon={<ArrowForwardIcon />}
                >
                  {strings.fixNextStep}
                </Button>
              </Stack>
            )
          )}
        >
          <Typography variant="body2" component="div" sx={{ fontWeight: 600, mb: 0.5 }}>
            {strings.itemsLeftTitle.replace('{count}', String(Math.max(blockedReasons.length, 1)))}
          </Typography>
          <Typography variant="body2">{exportLockGap.label}</Typography>
        </Alert>
      ) : null}

      {blockedReasons.length > 1 ? (
        <Alert severity="info" sx={{ mb: 1.5 }}>
          <Typography variant="body2" component="div" sx={{ fontWeight: 600, mb: 0.5 }}>
            {strings.moreGapsTitle}
          </Typography>
          <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
            {blockedReasons.slice(0, 4).map((reason) => {
              const link = remediationLinkForBlockedReason(reason);
              return (
                <li key={reason}>
                  <Typography variant="body2" component="span">
                    {reason}
                    {link ? (
                      <>
                        {' '}
                        <Button
                          component={RouterLink}
                          to={link}
                          size="small"
                          sx={{ minWidth: 0, p: 0, verticalAlign: 'baseline', textTransform: 'none' }}
                        >
                          {strings.fixNow}
                        </Button>
                      </>
                    ) : null}
                  </Typography>
                </li>
              );
            })}
          </Box>
        </Alert>
      ) : null}

      {lastRemediation ? (
        <Alert severity="info" sx={{ mb: 1.5 }}>
          <Typography variant="body2" sx={{ fontWeight: 600, mb: 0.5 }}>
            {lastRemediation.reportReadinessLabel || strings.readinessRequired}
          </Typography>
          {lastRemediation.filingDisclaimer ? (
            <Typography variant="body2" sx={{ mb: 0.5 }}>
              {lastRemediation.filingDisclaimer}
            </Typography>
          ) : null}
          {(lastRemediation.cbamBlockedReasons || []).map((reason) => (
            <Typography key={reason} variant="body2" display="block">
              {reason}
            </Typography>
          ))}
        </Alert>
      ) : null}

      <Stack spacing={1.25}>
        {verificationFormats.map((format) => (
          <Button
            key={format.id}
            variant="outlined"
            startIcon={busyFormatId === format.id ? <CircularProgress size={16} color="inherit" /> : <DownloadIcon />}
            disabled={busyFormatId !== null}
            onClick={() => void handleDownload(format)}
            sx={{ justifyContent: 'flex-start', textAlign: 'left' }}
            fullWidth
          >
            <Box>
              <Typography variant="body2" sx={{ fontWeight: 700 }}>
                {format.msmeLabel || format.label}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block">
                {format.msmeDescription || format.description}
              </Typography>
            </Box>
          </Button>
        ))}
        {statutoryFormats.map((format) => {
          const allowed = isExportFormatClientAllowed(format, readinessLevel);
          const requirement = formatRequirementLabel(format);

          if (allowed) {
            return (
              <Button
                key={format.id}
                variant="contained"
                color="success"
                startIcon={busyFormatId === format.id ? <CircularProgress size={16} color="inherit" /> : <DownloadIcon />}
                disabled={busyFormatId !== null}
                onClick={() => void handleDownload(format)}
                sx={{ justifyContent: 'flex-start', textAlign: 'left' }}
                fullWidth
              >
                <Box>
                  <Typography variant="body2" sx={{ fontWeight: 700 }}>
                    {format.msmeLabel || format.label}
                  </Typography>
                  <Typography variant="caption" sx={{ opacity: 0.9 }} display="block">
                    {format.msmeDescription || format.description}
                  </Typography>
                </Box>
              </Button>
            );
          }

          const fixLink = exportLockGap.link || remediationLinkForBlockedReason(blockedReasons[0] || '') || '/compliance';

          return (
            <Box
              key={format.id}
              sx={{
                border: 1,
                borderColor: 'divider',
                borderRadius: 1,
                p: 1.5,
              }}
            >
              <Typography variant="body2" sx={{ fontWeight: 700 }}>
                {format.msmeLabel || format.label}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                {strings.statutoryLockedHint
                  .replace('{format}', format.msmeLabel || format.label)
                  .replace('{requirement}', requirement)}
              </Typography>
              <Button
                component={RouterLink}
                to={fixLink}
                variant="outlined"
                size="small"
                endIcon={<ArrowForwardIcon />}
              >
                {strings.fixNextStep}
              </Button>
            </Box>
          );
        })}
      </Stack>
    </Box>
  );
};

export default ReportingStatutoryExports;
